package main

import (
	"bufio"
	"io"
	"strings"
	"testing"
)

func runTool(t *testing.T, tool func(io.Reader, *bufio.Writer) error, in string) string {
	t.Helper()
	var sb strings.Builder
	w := bufio.NewWriter(&sb)
	if err := tool(strings.NewReader(in), w); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if err := w.Flush(); err != nil {
		t.Fatal(err)
	}
	return sb.String()
}

func TestWordFreq(t *testing.T) {
	tests := []struct{ in, want string }{
		{"The cat and the hat.", "2 the\n1 and\n1 cat\n1 hat\n"},
		{"don't stop_me 4now, now-NOW", "3 now\n1 don\n1 me\n1 stop\n1 t\n"},
		{"", ""},
		{"123 \xff\xc3(", ""},
		{"k j i h g f e d c b a a", "2 a\n1 b\n1 c\n1 d\n1 e\n1 f\n1 g\n1 h\n1 i\n1 j\n"},
	}
	for _, tt := range tests {
		if got := runTool(t, wordFreq, tt.in); got != tt.want {
			t.Errorf("wordFreq(%q) = %q, want %q", tt.in, got, tt.want)
		}
	}
}

func TestLRU(t *testing.T) {
	tests := []struct{ in, want string }{
		{"2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n", "1\nNULL\n2\n"},
		{"2\nSET a 1\nSET b 2\nSET a 9\nSET c 3\nGET a\nGET b\nGET c", "9\nNULL\n3\n"},
		{"3\nSET x 1\nDEL x\nDEL x\nSIZE\nGET x\n", "1\n0\n0\nNULL\n"},
		{"2\nSET a 1\nSET b 2\nDEL a\nSET c 3\nSET d 4\nGET b\nGET c\nGET d\nSIZE\n", "1\nNULL\n3\n4\n2\n"},
	}
	for _, tt := range tests {
		if got := runTool(t, lruSim, tt.in); got != tt.want {
			t.Errorf("lruSim(%q) = %q, want %q", tt.in, got, tt.want)
		}
	}
}

func TestCalc(t *testing.T) {
	tests := []struct{ expr, want string }{
		{"1 + 2 * 3", "7"},
		{"-7 / 2", "-3"},
		{"-7 % 3", "-1"},
		{"7 % -3", "1"},
		{"10 - 4 - 3", "3"},
		{"--5", "5"},
		{"-2 * 3", "-6"},
		{"\t(1 + 2) * 3 ", "9"},
		{"(-9223372036854775807 - 1) % -1", "0"},
		{"-9223372036854775807 - 1", "-9223372036854775808"},
		{"(-9223372036854775807 - 1) / -1", "error"},
		{"-(-9223372036854775807 - 1)", "error"},
		{"9223372036854775807 + 1", "error"},
		{"9223372036854775808", "error"},
		{"3037000500 * 3037000500", "error"},
		{"1 / 0", "error"},
		{"1 % 0", "error"},
		{"(1 + 2", "error"},
		{"1 + 2)", "error"},
		{"()", "error"},
		{"1 2", "error"},
		{"+1", "error"},
		{"1 +", "error"},
		{"abc", "error"},
	}
	for _, tt := range tests {
		if got := runTool(t, calc, tt.expr+"\n"); got != tt.want+"\n" {
			t.Errorf("calc(%q) = %q, want %q", tt.expr, got, tt.want)
		}
	}
	if got := runTool(t, calc, "\n  \t\n"); got != "" {
		t.Errorf("blank lines produced %q", got)
	}
}

package main

import (
	"bufio"
	"errors"
	"io"
	"math"
	"strconv"
)

var (
	errSyntax   = errors.New("syntax error")
	errDivZero  = errors.New("division by zero")
	errOverflow = errors.New("overflow")
)

// calc evaluates one expression per input line and prints its value or "error".
// Blank lines (only spaces/tabs) produce no output.
func calc(r io.Reader, w *bufio.Writer) error {
	br := bufio.NewReaderSize(r, 1<<20)
	var ev evaluator
	for {
		line, err := readLine(br)
		if err != nil && err != io.EOF {
			return err
		}
		if !isBlank(line) {
			if v, e := ev.eval(line); e != nil {
				w.WriteString("error\n")
			} else {
				w.WriteString(strconv.FormatInt(v, 10))
				w.WriteByte('\n')
			}
		}
		if err == io.EOF {
			return nil
		}
	}
}

func isBlank(line []byte) bool {
	for _, c := range line {
		if c != ' ' && c != '\t' {
			return false
		}
	}
	return true
}

// Operator-stack entries. opNeg is unary minus; opParen marks an open '('.
const (
	opParen = '('
	opNeg   = 'n'
)

// precedence returns the binding strength of a stacked operator; '(' never
// pops, so it has the lowest.
func precedence(op byte) int {
	switch op {
	case '+', '-':
		return 1
	case '*', '/', '%':
		return 2
	case opNeg:
		return 3
	}
	return 0
}

// evaluator is an operator-precedence (shunting-yard) evaluator. It uses
// explicit stacks rather than recursion so that deeply nested input cannot
// exhaust the goroutine stack. Its buffers are reused between lines.
type evaluator struct {
	vals []int64
	ops  []byte
}

func (ev *evaluator) eval(s []byte) (int64, error) {
	ev.vals, ev.ops = ev.vals[:0], ev.ops[:0]
	expectOperand := true

	for i := 0; i < len(s); {
		c := s[i]
		switch {
		case c == ' ' || c == '\t':
			i++
		case expectOperand && isDigit(c):
			j := i
			for j < len(s) && isDigit(s[j]) {
				j++
			}
			v, err := parseLiteral(s[i:j])
			if err != nil {
				return 0, err
			}
			ev.vals = append(ev.vals, v)
			expectOperand = false
			i = j
		case expectOperand && c == '-':
			ev.ops = append(ev.ops, opNeg)
			i++
		case expectOperand && c == '(':
			ev.ops = append(ev.ops, opParen)
			i++
		case !expectOperand && (c == '+' || c == '-' || c == '*' || c == '/' || c == '%'):
			if err := ev.reduce(precedence(c)); err != nil {
				return 0, err
			}
			ev.ops = append(ev.ops, c)
			expectOperand = true
			i++
		case !expectOperand && c == ')':
			if err := ev.reduce(1); err != nil {
				return 0, err
			}
			if len(ev.ops) == 0 {
				return 0, errSyntax // unmatched ')'
			}
			ev.ops = ev.ops[:len(ev.ops)-1]
			i++
		default:
			return 0, errSyntax
		}
	}

	if expectOperand {
		return 0, errSyntax // empty input or missing operand
	}
	if err := ev.reduce(1); err != nil {
		return 0, err
	}
	if len(ev.ops) != 0 {
		return 0, errSyntax // unmatched '('
	}
	return ev.vals[0], nil
}

// reduce applies stacked operators while their precedence is at least minPrec.
// All operators are left-associative, so equal precedence also reduces.
func (ev *evaluator) reduce(minPrec int) error {
	for len(ev.ops) > 0 {
		op := ev.ops[len(ev.ops)-1]
		if precedence(op) < minPrec {
			return nil
		}
		ev.ops = ev.ops[:len(ev.ops)-1]

		n := len(ev.vals)
		if op == opNeg {
			v, err := neg(ev.vals[n-1])
			if err != nil {
				return err
			}
			ev.vals[n-1] = v
			continue
		}
		v, err := apply(op, ev.vals[n-2], ev.vals[n-1])
		if err != nil {
			return err
		}
		ev.vals = ev.vals[:n-1]
		ev.vals[n-2] = v
	}
	return nil
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func parseLiteral(digits []byte) (int64, error) {
	var v int64
	for _, d := range digits {
		x := int64(d - '0')
		if v > (math.MaxInt64-x)/10 {
			return 0, errOverflow
		}
		v = v*10 + x
	}
	return v, nil
}

func neg(a int64) (int64, error) {
	if a == math.MinInt64 {
		return 0, errOverflow
	}
	return -a, nil
}

func apply(op byte, a, b int64) (int64, error) {
	switch op {
	case '+':
		r := a + b
		if (a >= 0) == (b >= 0) && (r >= 0) != (a >= 0) {
			return 0, errOverflow
		}
		return r, nil
	case '-':
		r := a - b
		if (a >= 0) != (b >= 0) && (r >= 0) != (a >= 0) {
			return 0, errOverflow
		}
		return r, nil
	case '*':
		if a == 0 || b == 0 {
			return 0, nil
		}
		r := a * b
		if (a == -1 && b == math.MinInt64) || (b == -1 && a == math.MinInt64) || r/b != a {
			return 0, errOverflow
		}
		return r, nil
	case '/':
		if b == 0 {
			return 0, errDivZero
		}
		if a == math.MinInt64 && b == -1 {
			return 0, errOverflow
		}
		return a / b, nil
	case '%':
		if b == 0 {
			return 0, errDivZero
		}
		if b == -1 {
			return 0, nil // avoids the MinInt64 % -1 trap; the result is always 0
		}
		return a % b, nil
	}
	panic("calc: unknown operator " + string(op))
}

package main

import (
	"bufio"
	"bytes"
	"io"
	"strconv"
)

// lruCache is a fixed-capacity LRU cache. Entries live in a slice and are
// linked by index into a circular doubly linked list whose sentinel is
// node 0; the sentinel's next is the most recently used entry and its prev
// the least recently used. Slots released by Del are chained through next
// into a free list rooted at free (0 means empty).
type lruCache struct {
	capacity int
	index    map[string]int32
	nodes    []lruNode
	free     int32
}

type lruNode struct {
	key, value string
	prev, next int32
}

func newLRU(capacity int) *lruCache {
	hint := min(capacity, 1<<16)
	return &lruCache{
		capacity: capacity,
		index:    make(map[string]int32, hint),
		nodes:    make([]lruNode, 1, hint+1),
	}
}

// Len returns the number of keys held.
func (c *lruCache) Len() int { return len(c.index) }

// Get returns the value for key and marks it most recently used.
func (c *lruCache) Get(key []byte) (string, bool) {
	i, ok := c.index[string(key)]
	if !ok {
		return "", false
	}
	c.moveToFront(i)
	return c.nodes[i].value, true
}

// Set inserts or overwrites key, marks it most recently used and evicts the
// least recently used key if the cache is over capacity.
func (c *lruCache) Set(key, value []byte) {
	if i, ok := c.index[string(key)]; ok {
		c.nodes[i].value = string(value)
		c.moveToFront(i)
		return
	}

	var i int32
	switch {
	case len(c.index) >= c.capacity:
		// Evict the least recently used entry and reuse its slot.
		i = c.nodes[0].prev
		c.unlink(i)
		delete(c.index, c.nodes[i].key)
	case c.free != 0:
		i = c.free
		c.free = c.nodes[i].next
	default:
		c.nodes = append(c.nodes, lruNode{})
		i = int32(len(c.nodes) - 1)
	}

	k := string(key)
	c.nodes[i].key, c.nodes[i].value = k, string(value)
	c.index[k] = i
	c.pushFront(i)
}

// Del removes key and reports whether it was present.
func (c *lruCache) Del(key []byte) bool {
	i, ok := c.index[string(key)]
	if !ok {
		return false
	}
	c.unlink(i)
	delete(c.index, c.nodes[i].key)
	c.nodes[i] = lruNode{next: c.free}
	c.free = i
	return true
}

func (c *lruCache) moveToFront(i int32) {
	if c.nodes[0].next != i {
		c.unlink(i)
		c.pushFront(i)
	}
}

func (c *lruCache) unlink(i int32) {
	n := &c.nodes[i]
	c.nodes[n.prev].next = n.next
	c.nodes[n.next].prev = n.prev
}

func (c *lruCache) pushFront(i int32) {
	first := c.nodes[0].next
	c.nodes[i].prev, c.nodes[i].next = 0, first
	c.nodes[first].prev = i
	c.nodes[0].next = i
}

// lruSim reads a capacity line followed by cache commands from r and writes
// the command results to w. Malformed command lines are ignored.
func lruSim(r io.Reader, w *bufio.Writer) error {
	br := bufio.NewReaderSize(r, 1<<20)

	first, err := readLine(br)
	if err != nil && err != io.EOF {
		return err
	}
	capacity, perr := strconv.Atoi(string(bytes.TrimSpace(first)))
	if perr != nil || capacity < 1 {
		return nil // no valid capacity, so there is nothing to simulate
	}
	cache := newLRU(capacity)

	for err == nil {
		var line []byte
		line, err = readLine(br)
		if err != nil && err != io.EOF {
			return err
		}
		execLRU(cache, line, w)
	}
	return nil
}

func execLRU(c *lruCache, line []byte, w *bufio.Writer) {
	cmd, rest, _ := bytes.Cut(line, []byte{' '})
	switch string(cmd) {
	case "SET":
		if key, value, ok := bytes.Cut(rest, []byte{' '}); ok {
			c.Set(key, value)
		}
	case "GET":
		if v, ok := c.Get(rest); ok {
			w.WriteString(v)
		} else {
			w.WriteString("NULL")
		}
		w.WriteByte('\n')
	case "DEL":
		if c.Del(rest) {
			w.WriteString("1\n")
		} else {
			w.WriteString("0\n")
		}
	case "SIZE":
		w.WriteString(strconv.Itoa(c.Len()))
		w.WriteByte('\n')
	}
}

// readLine returns the next line without its "\n" or "\r\n" terminator.
// The returned slice is only valid until the next read. At end of input it
// returns the final (possibly empty) line together with io.EOF.
func readLine(br *bufio.Reader) ([]byte, error) {
	line, err := br.ReadSlice('\n')
	if err == bufio.ErrBufferFull {
		buf := append([]byte(nil), line...)
		for err == bufio.ErrBufferFull {
			line, err = br.ReadSlice('\n')
			buf = append(buf, line...)
		}
		line = buf
	}
	line = bytes.TrimSuffix(line, []byte{'\n'})
	line = bytes.TrimSuffix(line, []byte{'\r'})
	return line, err
}

// Command app bundles three independent stdin/stdout tools: wordfreq, lru and calc.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

const usage = "usage: app <wordfreq|lru|calc>"

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, usage)
		os.Exit(2)
	}

	var run func(io.Reader, *bufio.Writer) error
	switch os.Args[1] {
	case "wordfreq":
		run = wordFreq
	case "lru":
		run = lruSim
	case "calc":
		run = calc
	default:
		fmt.Fprintln(os.Stderr, usage)
		os.Exit(2)
	}

	out := bufio.NewWriterSize(os.Stdout, 64*1024)
	err := run(os.Stdin, out)
	if ferr := out.Flush(); err == nil {
		err = ferr
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

package main

import (
	"bufio"
	"io"
	"strconv"
)

// topN is the number of words wordFreq reports.
const topN = 10

type wordCount struct {
	word  string
	count int
}

// before reports whether a ranks ahead of b: higher count first, then word ascending.
func (a wordCount) before(b wordCount) bool {
	if a.count != b.count {
		return a.count > b.count
	}
	return a.word < b.word
}

// wordFreq prints the topN most frequent case-folded ASCII-letter words in r.
func wordFreq(r io.Reader, w *bufio.Writer) error {
	data, err := io.ReadAll(r)
	if err != nil {
		return err
	}

	counts := make(map[string]*int)
	for i := 0; i < len(data); {
		if !isLetter(data[i]) {
			i++
			continue
		}
		start := i
		for ; i < len(data) && isLetter(data[i]); i++ {
			data[i] |= 0x20 // ASCII lowercase
		}
		word := data[start:i]
		if p, ok := counts[string(word)]; ok {
			*p++
		} else {
			n := 1
			counts[string(word)] = &n
		}
	}

	for _, wc := range top(counts, topN) {
		w.WriteString(strconv.Itoa(wc.count))
		w.WriteByte(' ')
		w.WriteString(wc.word)
		w.WriteByte('\n')
	}
	return nil
}

// top returns the n highest-ranked entries of counts, in rank order.
func top(counts map[string]*int, n int) []wordCount {
	best := make([]wordCount, 0, n+1)
	for word, p := range counts {
		wc := wordCount{word, *p}
		if len(best) == n && !wc.before(best[n-1]) {
			continue
		}
		// Insertion into a small sorted slice.
		j := len(best)
		best = append(best, wc)
		for ; j > 0 && wc.before(best[j-1]); j-- {
			best[j] = best[j-1]
		}
		best[j] = wc
		if len(best) > n {
			best = best[:n]
		}
	}
	return best
}

func isLetter(c byte) bool {
	return (c|0x20) >= 'a' && (c|0x20) <= 'z'
}
